package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMsDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Berlindung Daripada Jiran Yang Buruk", "Ya Allah, sesungguhnya aku berlindung kepada-Mu daripada jiran yang jahat di tempat kediaman yang kekal, kerana jiran yang sedang dalam perjalanan terus berjalan.", "Untuk perlindungan daripada jiran yang jahat.", "Nabi ﷺ memerintahkan mencari perlindungan daripada ini."),
        "dua_ishfi_abdak" to DuaText("Untuk Pemulihan Orang Sakit", "Ya Allah, sembuhkanlah hambaMu ini agar dia menghadapi musuh bagiMu atau berjalan untuk solat untukMu.", "Bagi orang sakit ketika menziarahinya.", "Nabi ﷺ mengajar mengatakan ini untuk orang sakit."),
        "dua_la_mania" to DuaText("Tiada Yang Boleh Menahan Apa yang Anda Berikan", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Kepunyaan-Nya kerajaan dan kepunyaan-Nya pujian, dan Dia Maha Kuasa atas segala sesuatu. Ya Allah, tidak ada yang dapat menahan apa yang Engkau berikan dan tidak ada yang dapat memberikan apa yang Engkau tahan, dan harta orang-orang kaya tidak berguna terhadap-Mu.", "Selepas salam solat fardhu.", "Nabi ﷺ berkata demikian selepas setiap solat fardhu."),
        "dua_slaughtering" to DuaText("Ketika Menyembelih Binatang", "Dengan nama Allah, dan Allah Maha Besar.", "Ketika mengorbankan atau menyembelih binatang.", "Nabi ﷺ mengucapkan Bismillah dan takbir pada waktu korban."),
        "dua_undressing" to DuaText("Semasa Menanggalkan Pakaian", "Dengan nama Allah.", "Semasa menanggalkan pakaian (untuk mandi atau menukar pakaian).", "Ia menjadi tabir antara mata jin dan aurat seseorang."),
        "dua_ilbas_jadidan" to DuaText("Melihat Seseorang dengan Pakaian Baru", "Pakai baru, hidup terpuji dan mati syahid.", "Apabila melihat saudara muslim yang berpakaian baru.", "Nabi ﷺ berdoa ini apabila melihat Umar (RA) dalam pakaian baru."),
        "dua_hajj_la_riya" to DuaText("Haji Bebas Menunjuk-nunjuk", "Ya Allah, (jadikanlah) haji dengan tidak menunjuk-nunjuk dan tidak mencari kemasyhuran.", "Untuk keikhlasan ketika berniat haji.", "Nabi ﷺ berdoa ini pada masa haji."),
        "dua_q_muslimayni_laka" to DuaText("Doa Ibrahim & Ismail (AS) — Jadikan Kami Tunduk", "Ya Tuhan kami, jadikanlah kami berdua orang yang tunduk patuh kepadaMu dan dari anak cucu kami umat yang tunduk patuh kepada Engkau. Tunjukkan kepada kami ibadah kami dan terimalah taubat kami. Sesungguhnya Engkau Maha Penerima taubat lagi Maha Penyayang.", "Doa penyerahan diri dan keturunan.", "Doa yang dilakukan semasa membina Kaabah."),
        "dua_q_iftah_baynana" to DuaText("Doa Shu'aib (AS) — Hakim Antara Kita", "Ya Tuhan kami, putuskanlah antara kami dan kaum kami dengan kebenaran, dan Engkaulah sebaik-baik hakim.", "Untuk penghakiman antara kebenaran dan kebatilan.", "Doa Syu'aib (AS) ketika kaumnya mendustakannya."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua Musa (AS) — Tidak Pernah Menolong Penjenayah", "Ya Tuhanku, karena nikmat yang telah Engkau anugerahkan kepadaku, aku sekali-kali tidak akan menjadi penolong bagi orang-orang yang berdosa.", "Syukur atas nikmat Allah dan ikrar untuk tidak menolong orang yang zalim.", "Ikrar Musa (AS) selepas dia bertaubat."),
        "dua_q_nuh_unsurni" to DuaText("Doa Nuh (AS) — Tolonglah Aku, Mereka Menafikan Aku", "Tuhanku, tolonglah aku, kerana mereka telah mendustakan aku.", "Apabila orang mendustakanmu dan menolak kebenaran.", "Doa Nuh (AS), yang dimakbulkan."),
        "dua_q_ihkum_bil_haqq" to DuaText("Tuhanku, Hakimlah Dengan Kebenaran", "Tuhanku, hukumlah dengan kebenaran. Dan Tuhan kami adalah Yang Maha Penyayang, yang dimohon pertolongan-Nya terhadap apa yang kamu sifatkan.", "Dalam menghadapi pembohongan dan tuduhan palsu.", "Doa yang diajarkan kepada Nabi ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Berlindung Daripada Hutang dan Musuh yang Memusnahkan", "Ya Allah, aku berlindung kepada-Mu daripada dibelenggu hutang, daripada dikuasai musuh dan daripada kemegahan musuh.", "Perlindungan daripada beban hutang dan penguasaan musuh.", "Nabi ﷺ pernah berlindung dari perkara-perkara ini."),
        "dua_faqr_qillah_dhillah" to DuaText("Berlindung Daripada Kemiskinan dan Kehinaan", "Ya Allah, aku berlindung kepada-Mu dari kemiskinan, kekurangan dan kehinaan, dan dari menzalimi orang lain atau dizalimi.", "Agar selamat dari kesusahan, kemahuan dan kehinaan.", "Sebuah perlindungan yang diajarkan oleh Nabi ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Ampuni, Kasihani, Bimbing, Sembuh, Sediakan", "Ya Allah, ampunilah aku, rahmatilah aku, bimbinglah aku, berikanlah kesejahteraan kepadaku dan berikanlah rezeki kepadaku.", "Nabi ﷺ mengajarkan doa ini, bersama dengan doa, kepada orang Islam yang baru.", "Nabi ﷺ bersabda: Kalimah ini mengumpulkan untukmu dunia dan akhirat."),
        "dua_ruku_laka_raka_tu" to DuaText("Dalam Ruku — Kepada Mu Aku Tunduk", "Ya Allah, kepadaMu aku sujud, kepadaMu aku beriman dan kepadaMu aku berserah diri. Pendengaranku, penglihatanku, fikiranku, tulangku dan urat-uratku direndahkan di hadapanMu.", "Dalam ruku (terutama dalam solat sunat).", "Nabi ﷺ membaca ini dalam ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("Dalam Sujud - Kepada-Mu aku sujud", "Ya Allah, kepadaMu aku bersujud, kepadaMu aku beriman dan kepadaMu aku berserah diri. Wajahku telah sujud kepada Tuhan yang menciptakannya, membentuknya dan mengeluarkan pendengaran dan penglihatannya. Maha Suci Allah, sebaik-baik pencipta.", "Dalam sujud (terutama dalam solat sunat).", "Nabi ﷺ membaca ini dalam sujud."),
        "dua_ruku_sujood_subhanaka" to DuaText("Maha Suci Engkau, Tuhan kami - Ampunilah Aku", "Maha Suci Engkau ya Allah, Tuhan kami, dan segala puji bagi-Mu. Ya Allah, ampunilah aku.", "Dalam ruku dan sujud.", "Aisyah (RA): Nabi ﷺ sering berkata demikian dalam ruku dan sujud."),
        "dua_q_musa_li_akhi" to DuaText("Doa Musa (AS) — Maafkan Aku dan Saudaraku", "Ya Tuhanku, ampunilah aku dan saudaraku dan masukkanlah kami ke dalam rahmatMu, sesungguhnya Engkau Maha Penyayang di antara para penyayang.", "Kemaafan untuk diri sendiri dan saudara atau orang tersayang.", "Doa Musa (AS) untuk Harun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Aku Serahkan Urusanku Kepada Allah", "Dan aku serahkan urusanku kepada Allah. Sesungguhnya Allah Maha Melihat akan hamba-hambaNya.", "Apabila orang menentangmu dan perkara itu hendaklah diserahkan kepada Allah.", "Kata-kata orang mukmin dari kaum Firaun; Kemudian Allah melindunginya dari tipu daya jahat mereka."),
        "dua_q_hawariyyun" to DuaText("Doa Para Murid — Catatkan Kami Bersama Saksi", "Ya Tuhan kami, kami telah beriman kepada apa yang Engkau turunkan dan kami telah mengikuti rasul, maka catatlah kami di antara orang-orang yang menjadi saksi.", "Untuk keteguhan dalam iman dan dalam mengikuti Rasul.", "Doa para pengikut Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Doa of Ibrahim (AS) — Jangan Aibkan Aku", "Dan janganlah kamu hinakan aku pada hari mereka dibangkitkan.", "Agar selamat dari kehinaan pada hari kiamat.", "Doa Ibrahim (AS) untuk akhirat."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar — Untuk Awak Saya Puasa", "Ya Allah, untukMu aku berpuasa dan dengan rezekiMu aku berbuka.", "Ketika berbuka puasa (doa iftar yang terkenal).", "Nabi ﷺ berkata demikian ketika berbuka puasa. Ia adalah riwayat mursal yang dikuatkan dengan riwayat lain; membacanya ketika berbuka puasa adalah amalan Hanafi dan majoriti."),
        "dua_iftar_ibn_umar" to DuaText("Iftar — Dengan Rahmat-Mu yang Maha Luas, Ampunilah Aku", "Ya Allah, aku memohon kepada-Mu dengan rahmat-Mu yang meliputi segala sesuatu untuk mengampuni aku.", "Pada iftar — Abdullah ibn Amr (RA) membuat doa ini; Doa orang yang berpuasa ketika berbuka puasa tidak ditolak.", "Hadis: Doa orang yang berpuasa pada waktu berbuka puasa tidak ditolak."),
        "dua_inni_saim" to DuaText("Apabila Diprovokasi Ketika Berpuasa", "Saya berpuasa, saya berpuasa.", "Apabila seseorang menghina anda atau bergaduh dengan anda semasa berpuasa.", "Nabi ﷺ bersabda: Puasa adalah perisai, maka orang yang berpuasa tidak boleh berkata-kata keji atau berbuat jahil — jika ada yang bertengkar, ucapkan ini dua kali."),
        "dua_eid_takbeer" to DuaText("Takbir dalam perjalanan ke hari raya", "Allah Maha Besar, Allah Maha Besar, tiada Tuhan selain Allah, dan Allah Maha Besar, Allah Maha Besar, dan segala puji bagi Allah.", "Dari malam melihat bulan sehinggalah solat Idul Fitri, terutama dalam perjalanan ke bumi hari raya.", "Perintah Al-Quran: 'supaya kamu menyempurnakan hitungan dan menyatakan kebesaran Allah' (al-Baqarah 2:185). Ibn Mas'ud (RA) mengucapkan takbir ini."),
        "dua_ahsin_aqibatana" to DuaText("Jadikan Akhir Kita Baik dalam Semua Hal Ehwal", "Ya Allah, jadikanlah akhir kami baik dalam segala urusan, dan peliharalah kami dari kehinaan di dunia dan siksa di akhirat.", "Untuk hasil yang baik dalam setiap perkara.", "Sesiapa yang melakukan doa ini dan mati sebelum diuji dia mati (selamat daripada cubaan)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Aku Memohon Karunia dan Rahmat-Mu", "Ya Allah, sesungguhnya aku memohon kepada-Mu karunia dan rahmat-Mu, karena tidak ada yang memilikinya kecuali Engkau.", "Apabila memohon rezeki dan rahmat.", "Tetamu datang kepada Nabi ﷺ ketika tidak ada makanan; dia membuat doa ini, dan kemudian hadiah tiba."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Kata-kata yang diajarkan kepada Badwi", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Allah Maha Besar, Maha Besar; banyak pujian bagi Allah; Maha Suci Allah, Tuhan sekalian alam; dan tiada daya dan kekuatan melainkan dengan pertolongan Allah Yang Maha Perkasa lagi Maha Bijaksana.", "Ungkapan zikir dan doa yang komprehensif - diajarkan kepada seorang Badwi.", "Selepas ini dia diajar mengucap 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Maafkan Apa yang Saya Hantar Sebelum dan Selepas", "Ya Allah, ampunilah dosa-dosaku sebelum dan sesudahnya, apa yang aku lakukan secara diam-diam dan apa yang aku lakukan secara terang-terangan, keterlaluanku, dan apa yang Engkau lebih mengetahui daripadaku. Engkaulah yang membawa ke hadapan dan yang mengundurkan; tiada Tuhan selain Engkau.", "Selepas tashahhud dan selawat, sebelum salam.", "Nabi ﷺ membaca ini pada akhir solat, antara tasyahhud dan salam."),
        "dua_jiddi_wa_hazli" to DuaText("Maafkan Kesungguhan Saya dan Gurauan Saya", "Ya Allah, ampunilah dosa-dosa yang aku lakukan secara serius dan bergurau, secara tidak sengaja dan tidak sengaja - dan semua itu ada padaku.", "Pengampunan untuk setiap jenis dosa, yang diketahui dan tidak diketahui.", "Istighfar Nabi yang menyeluruh ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Selepas Ruku — Pujian Memenuhi Syurga", "Ya Tuhan kami, kepunyaan-Mu segala pujian, sepenuh langit, sepenuh bumi, dan sepenuh hati sesudah itu.", "Setelah bangkit dari ruku, bersama dengan 'Rabbana lakal-hamd'.", "Nabi ﷺ bersabda demikian pada bangkit dari ruku."),
        "dua_istiftah_kabira" to DuaText("Allah Maha Besar, Maha Terpuji", "Allah Maha Besar, Maha Besar; banyak pujian bagi Allah; dan Maha Suci Allah pagi dan petang.", "Ketika memulakan solat (salah satu bentuk pujian pembuka).", "Nabi ﷺ bersabda: dibukakan baginya pintu-pintu syurga."),
        "dua_q_ashku_bathhi" to DuaText("Doa Yaqub (AS) — Aku Mengadu Hanya Kepada Allah", "Aku mengadukan kesusahan dan kesedihanku hanya kepada Allah.", "Dalam kesedihan dan perpisahan yang mendalam.", "Ya'qub (AS) berkata demikian dalam perpisahannya dengan Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah Sebaik-baik Pelindung", "Allah adalah sebaik-baik Pelindung, dan Dia Maha Penyayang di antara para penyayang.", "Apabila menghantar anak atau orang tersayang dalam perjalanan.", "Ya'qub (AS) berkata demikian sambil menyerahkan anaknya kepada Allah."),
        "dua_q_aqraba_rashada" to DuaText("Semoga Tuhanku Bimbing Aku Lebih Dekat Kepada Kanan", "Mudah-mudahan Tuhanku akan memberiku petunjuk kepada yang lebih dekat daripada ini kepada akhlak yang benar.", "Apabila mencari jalan yang lebih baik dalam sesuatu perkara.", "Nabi ﷺ disuruh mengatakan ini apabila terlupa."),
        "dua_q_sawa_as_sabil" to DuaText("Doa Musa (AS) — Bimbinglah Aku ke Jalan Yang Benar", "Semoga Tuhanku memberi petunjuk kepadaku ke jalan yang benar.", "Apabila memulakan perjalanan baru atau jalan yang tidak dikenali.", "Musa (AS) berkata demikian sambil berpaling ke arah Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("Jangan Tempatkan Aku Dikalangan Orang Yang Zalim", "Ya Tuhanku, janganlah Engkau jadikan aku dalam golongan orang-orang yang zalim.", "Doa memohon kepada Allah agar menjauhkan seseorang dari orang-orang yang zalim.", "Doa memohon kepada Allah agar menjauhkan seseorang dari orang-orang yang zalim."),
        "dua_q_do_not_make_us_trial" to DuaText("Jangan Jadikan Kami Ujian", "Ya Tuhan kami, janganlah Engkau jadikan kami cobaan bagi orang-orang kafir, dan ampunilah kami ya Tuhan kami. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana.", "Doa Ibrahim (AS) dan para sahabatnya.", "Doa Ibrahim (AS) dan para sahabatnya."),
        "dua_morning_witness" to DuaText("Saksi Pagi Tauhid", "Ya Allah, aku telah memasuki waktu pagi menyeru kepada-Mu, para pembawa Arasy-Mu, para malaikat-Mu dan seluruh makhluk-Mu untuk bersaksi bahawa Engkau adalah Allah, tiada Tuhan selain Engkau, semata-mata, tiada sekutu bagi-Mu, dan bahawa Muhammad ﷺ adalah hamba dan Rasul-Mu.", "Riwayat tersebut menyebutkan mengucapkannya empat kali pada waktu pagi.", "Riwayat tersebut menyebutkan mengucapkannya empat kali pada waktu pagi."),
    )
}
